import type { InputHTMLAttributes } from "react";
import { styled } from "styled-components";
import Text from "../Text/Text";

interface SliderLabelProps {
  progress: string;
}

interface StyledInputProps extends InputHTMLAttributes<HTMLInputElement> {
  $isMax: boolean;
}

interface DisabledProp {
  disabled?: boolean;
}

const getCursorStyle = ({ disabled = false }: DisabledProp) => {
  return disabled ? "not-allowed" : "cursor";
};

export const bunnyHeadMax = `"data:image/svg+xml;base64,"`;
export const bunnyHeadMain = `"data:image/svg+xml;base64,"`;
export const bunnyButt = `"data:image/svg+xml,%3Csvg width='15' height='32' viewBox='0 0 15 32' fill='none' xmlns='http://www.w3.org/2000/svg'%3E%3Cpath d='M9.58803 20.8649C7.72935 21.3629 8.02539 24.0334 8.76388 26.7895C9.50238 29.5456 10.5812 32.0062 12.4399 31.5082C14.2986 31.0102 15.2334 28.0099 14.4949 25.2538C13.7564 22.4978 11.4467 20.3669 9.58803 20.8649Z' fill='%230098A1'/%3E%3Cpath d='M1 24.4516C1 20.8885 3.88849 18 7.45161 18H15V28H4.54839C2.58867 28 1 26.4113 1 24.4516Z' fill='%231FC7D4'/%3E%3Cpath d='M6.11115 17.2246C6.79693 18.4124 5.77784 19.3343 4.52793 20.0559C3.27802 20.7776 1.97011 21.1992 1.28433 20.0114C0.598546 18.8236 1.1635 17.1151 2.41341 16.3935C3.66332 15.6718 5.42537 16.0368 6.11115 17.2246Z' fill='%2353DEE9'/%3E%3Cpath d='M1.64665 23.6601C0.285995 25.0207 1.87759 27.1854 3.89519 29.203C5.91279 31.2206 8.07743 32.8122 9.43808 31.4515C10.7987 30.0909 10.1082 27.0252 8.09058 25.0076C6.07298 22.99 3.0073 22.2994 1.64665 23.6601Z' fill='%231FC7D4'/%3E%3C/svg%3E"`;

export const getBaseThumbStyles = ({ $isMax, disabled }: StyledInputProps) => `
  -webkit-appearance: none;
  background-image: url(${$isMax ? bunnyHeadMax : bunnyHeadMain});
  background-color: transparent;
  box-shadow: none;
  border: 0;
  cursor: ${getCursorStyle};
  width: 24px;
  height: 32px;
  filter: ${disabled ? "grayscale(100%)" : "none"};
  transform: translate(-2px, -2px);
  transition: 200ms transform;
  &:hover {
    transform: ${disabled ? "scale(1) translate(-2px, -2px)" : "scale(1.1) translate(-3px, -3px)"};
  }
`;

export const SliderLabelContainer = styled.div`
  bottom: 0;
  position: absolute;
  left: 14px;
  width: calc(100% - 30px);
`;

export const SliderLabel = styled(Text)<SliderLabelProps>`
  bottom: 0;
  font-size: 12px;
  left: ${({ progress }) => progress};
  position: absolute;
  text-align: center;
  min-width: 24px; // Slider thumb size
`;

export const BunnyButt = styled.div<DisabledProp>`
  background: url(${bunnyButt}) no-repeat;
  height: 32px;
  filter: ${({ disabled }) => (disabled ? "grayscale(100%)" : "none")};
  position: absolute;
  width: 15px;
`;

export const BunnySlider = styled.div`
  position: absolute;
  left: 14px;
  width: calc(100% - 14px);
`;

export const StyledInput = styled.input<StyledInputProps>`
  /*
   * width:100% is required so the range input fills the BunnySlider
   * wrapper. Without it the browser defaults to ~129px and the bunny
   * thumb sits on a narrow invisible strip that does not line up with
   * the visible BarBackground/BarProgress divs (which are 100% wide).
   */
  width: 100%;
  cursor: ${getCursorStyle};
  height: 32px;
  position: relative;
  &::-webkit-slider-thumb {
    ${getBaseThumbStyles}
  }
  &::-moz-range-thumb {
    ${getBaseThumbStyles}
  }
  &::-ms-thumb {
    ${getBaseThumbStyles}
  }
`;

export const BarBackground = styled.div<DisabledProp>`
  background-color: ${({ theme, disabled }) => theme.colors[disabled ? "textDisabled" : "inputSecondary"]};
  height: 2px;
  position: absolute;
  top: 18px;
  width: 100%;
`;

export const BarProgress = styled.div<DisabledProp>`
  background-color: ${({ theme }) => theme.colors.primary};
  filter: ${({ disabled }) => (disabled ? "grayscale(100%)" : "none")};
  height: 10px;
  position: absolute;
  top: 18px;
`;

/* ── Dotted variant (storybook `.op-slider`) ──────────────────────────── */

interface DottedDisabledProp {
  $disabled?: boolean;
}

export const DottedRoot = styled.div`
  position: relative;
  height: 37px;
  overflow: visible;
  margin: 4px 0;
  cursor: pointer;
  &[aria-disabled="true"] {
    cursor: not-allowed;
  }
`;

export const DottedRail = styled.div<DottedDisabledProp>`
  position: absolute;
  left: 10px;
  right: 10px;
  top: 24px;
  height: 2px;
  background: ${({ theme, $disabled }) => ($disabled ? theme.colors.textDisabled : theme.colors.cardBorder)};
  border-radius: 2px;
  pointer-events: none;
`;

export const DottedBunnyBar = styled.div<DottedDisabledProp & { $width: string }>`
  position: absolute;
  left: 10px;
  top: 18px;
  height: 12px;
  border-radius: 6px;
  background: ${({ theme }) => theme.colors.primary};
  width: ${({ $width }) => $width};
  filter: ${({ $disabled }) => ($disabled ? "grayscale(100%)" : "none")};
  pointer-events: none;
`;

export const DottedBunnyBack = styled.div`
  position: absolute;
  left: 0;
  top: 15px;
  pointer-events: none;
`;

export const DottedBunnyFront = styled.div<DottedDisabledProp>`
  position: absolute;
  top: 0;
  width: 32px;
  height: 48px;
  cursor: ${({ $disabled }) => ($disabled ? "not-allowed" : "grab")};
  user-select: none;
  -webkit-user-select: none;
  filter: ${({ $disabled }) => ($disabled ? "grayscale(100%)" : "none")};
  &:active {
    cursor: grabbing;
  }
`;

export const DottedStop = styled.button<DottedDisabledProp & { $filled: boolean }>`
  position: absolute;
  top: 20px;
  width: 8px;
  height: 8px;
  border-radius: 50%;
  border: none;
  padding: 0;
  cursor: ${({ $disabled }) => ($disabled ? "not-allowed" : "pointer")};
  transform: translateX(-4px);
  transition: background 0.12s, transform 0.1s;
  background: ${({ theme, $filled, $disabled }) =>
    $disabled ? theme.colors.textDisabled : $filled ? theme.colors.primary : theme.colors.cardBorder};
  &:hover {
    transform: translateX(-4px) ${({ $disabled }) => ($disabled ? "" : "scale(1.3)")};
  }
`;
